def process(density2014, density2018) -> pd.DataFrame:
    import pandas as pd

    def peak(df: pd.DataFrame) -> float:
        # choose the first column that looks like density
        candidates = [c for c in df.columns if 'dens' in c.lower()]
        if not candidates:
            # fallback: numeric columns
            numcols = df.select_dtypes(include='number').columns.tolist()
            if not numcols:
                raise ValueError('No numeric columns found to compute peak density.')
            col = numcols[0]
        else:
            # prefer 'rho' if present
            rho = [c for c in candidates if c.lower() in ('rho', 'rho_n', 'rho_nrlmsise00', 'density', 'mass_density')]
            col = rho[0] if rho else candidates[0]
        s = pd.to_numeric(df[col], errors='coerce')
        return float(s.max())

    p2014 = peak(density2014)
    p2018 = peak(density2018)
    ratio = p2014 / p2018
    return pd.DataFrame([{
        'peak2014': p2014,
        'peak2018': p2018,
        'ratio': ratio
    }])
